// polls for case updates only when user is viewing relevant content

class ConditionalPoller {
    constructor(caseGuid, config = {}) {
        this.caseGuid = caseGuid;
        this.interval = config.interval || 5000;
        
        this.activeTab = null;
        this.activeMediaSubTab = null;
        this.isCommentPanelOpen = false;
        
        // start with null so first poll gets all data, then use server_time
        this.lastModified = {
            comments: null,
            media: {
                audio: null,
                video: null,
                image: null
            },
            documents: null,
            notes: null
        };
        
        this.timerId = null;
        this.isUserIdle = false;
        this.isTabHidden = false;
        
        this.callbacks = {
            onFetchCommentUpdates: {
                handler: config.onFetchCommentUpdates || null,
                callbackOverride: config.onFetchCommentUpdatesOverride || false
            },
            onFetchMediaUpdates: {
                handler: config.onFetchMediaUpdates || null,
                callbackOverride: config.onFetchMediaUpdatesOverride || false
            },
            onFetchDocumentUpdates: {
                handler: config.onFetchDocumentUpdates || null,
                callbackOverride: config.onFetchDocumentUpdatesOverride || false
            },
            onFetchNoteUpdates: {
                handler: config.onFetchNoteUpdates || null,
                callbackOverride: config.onFetchNoteUpdatesOverride || false
            }
        };
        
        this.setupUIStateTracking();
        this.setupUserActivityTracking();
        this.setupVisibilityTracking();
    }
    
    setupUIStateTracking() {
        this.isCommentPanelOpen = !document.body.classList.contains('PdfjsAnnotationExtension_Comment_hidden');
        
        const observer = new MutationObserver((mutations) => {
            mutations.forEach((mutation) => {
                if (mutation.attributeName === 'class') {
                    const wasOpen = this.isCommentPanelOpen;
                    this.isCommentPanelOpen = !document.body.classList.contains('PdfjsAnnotationExtension_Comment_hidden');
                    
                    // if (wasOpen !== this.isCommentPanelOpen) {
                    //     // console.log('comment panel:', this.isCommentPanelOpen ? 'opened' : 'closed');
                    // }
                }
            });
        });
        observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
        
        this.detectInitialActiveTab();
        
        document.addEventListener('shown.bs.tab', (e) => {
            const target = e.target.getAttribute('data-bs-target');
            
            if (target === '#media') {
                this.activeTab = 'media';
                this.detectActiveMediaSubTab();
            } else if (target === '#documents') {
                this.activeTab = 'documents';
                this.activeMediaSubTab = null;
            } else if (target === '#updates') {
                this.activeTab = 'notes';
                this.activeMediaSubTab = null;
            } else {
                if (target === '#audio' || target === '#video' || target === '#image') {
                    this.activeMediaSubTab = target.replace('#', '');
                } else {
                    this.activeTab = null;
                    this.activeMediaSubTab = null;
                }
            }
        });
    }
    
    detectActiveMediaSubTab() {
        const mediaSubTabs = ['audio', 'video', 'image'];
        for (const subTab of mediaSubTabs) {
            const pane = document.querySelector(`#${subTab}`);
            if (pane && pane.classList.contains('active')) {
                this.activeMediaSubTab = subTab;
                return;
            }
        }
        this.activeMediaSubTab = 'audio';
    }
    
    detectInitialActiveTab() {
        const activePane = document.querySelector('.tab-pane.active');
        if (activePane) {
            const paneId = activePane.id;
            if (paneId === 'media') {
                this.activeTab = 'media';
                this.detectActiveMediaSubTab();
            } else if (paneId === 'documents') {
                this.activeTab = 'documents';
            } else if (paneId === 'updates') {
                this.activeTab = 'notes';
            }
        }
    }
    
    setupUserActivityTracking() {
        let idleTimer = null;
        const idleThreshold = 5 * 60 * 1000;
        
        const resetIdleTimer = () => {
            clearTimeout(idleTimer);
            
            if (this.isUserIdle) {
                this.isUserIdle = false;
                this.startPolling();
            }
            
            idleTimer = setTimeout(() => {
                this.isUserIdle = true;
                this.stopPolling();
            }, idleThreshold);
        };
        
        ['mousedown', 'keydown', 'scroll', 'touchstart'].forEach(event => {
            document.addEventListener(event, resetIdleTimer, { passive: true });
        });
        
        resetIdleTimer();
    }
    
    setupVisibilityTracking() {
        document.addEventListener('visibilitychange', () => {
            this.isTabHidden = document.hidden;
            if (this.isTabHidden) {
                this.stopPolling();
            } else {
                this.startPolling();
            }
        });
    }

    getTimestamp() {
        let timestamp = new Date().toISOString();
        console.log('Generated timestamp for polling:', timestamp);
        return timestamp;
    }
    
    async pollComments() {
        if (!this.isCommentPanelOpen) {
            return;
        }
        
        // get current file from docviewer instance
        const currentFileGuid = window.docViewerInstance?.getCurrentFileuuid?.();
        if (!currentFileGuid) {
            return;
        }
        
        try {
            // use stored time or current time for first request
            const ifModifiedSince = this.lastModified.comments || this.getTimestamp();
            
            const params = new URLSearchParams({
                file: currentFileGuid,
                if_modified_since: ifModifiedSince
            });
            
            const response = await fetch(`/case/${this.caseGuid}/shared-comments?${params}`);
            if (!response.ok) return;
            
            const data = await response.json();
            
            if (data.status === 'success') {
                this.lastModified.comments = data.server_time;
                
                if (data.items && data.items.length > 0) {
                    await this.handleCommentsUpdate(data.items);
                }
            }
        } catch (error) {
            console.error('[ConditionalPoller] error polling comments:', error);
        }
    }
    
    async pollMedia() {
        if (this.activeTab !== 'media' || !this.activeMediaSubTab) return;
        
        // activeMediaSubTab is already 'audio', 'video', or 'image' - matches backend type parameter
        const mediaType = this.activeMediaSubTab;
        
        try {
            // use stored time or current time for first request
            const ifModifiedSince = this.lastModified.media[this.activeMediaSubTab] || this.getTimestamp();
            
            const params = new URLSearchParams({
                type: mediaType,
                if_modified_since: ifModifiedSince
            });
            
            const response = await fetch(`/case/${this.caseGuid}/media?${params}`);
            if (!response.ok) return;
            
            const data = await response.json();
            
            if (data.status === 'success') {
                this.lastModified.media[this.activeMediaSubTab] = data.server_time;
                
                if (data.items && data.items.length > 0) {
                    await this.handleMediaUpdate(this.activeMediaSubTab, data.items);
                }
            }
        } catch (error) {
            console.error(`[ConditionalPoller] error polling ${this.activeMediaSubTab}:`, error);
        }
    }
    
    async pollDocuments() {
        if (this.activeTab !== 'documents') return;
        
        try {
            // use stored time or current time for first request
            const ifModifiedSince = this.lastModified.documents || this.getTimestamp();
            
            const params = new URLSearchParams({
                if_modified_since: ifModifiedSince
            });
            
            const response = await fetch(`/case/${this.caseGuid}/documents?${params}`);
            if (!response.ok) return;
            
            const data = await response.json();
            
            if (data.status === 'success') {
                this.lastModified.documents = data.server_time;
                
                if (data.items && data.items.length > 0) {
                    await this.handleDocumentsUpdate(data.items);
                }
            }
        } catch (error) {
            console.error('[ConditionalPoller] error polling documents:', error);
        }
    }
    
    async pollNotes() {
        if (this.activeTab !== 'notes') return;
        
        try {
            // use stored time or current time for first request
            const ifModifiedSince = this.lastModified.notes || new Date().toISOString();
            
            const params = new URLSearchParams({
                if_modified_since: ifModifiedSince
            });
            console.log('Polling notes with params:', params.toString());
            
            const response = await fetch(`/case/${this.caseGuid}/case-notes-updates?${params}`);
            if (!response.ok) return;
            
            const data = await response.json();
            
            if (data.status === 'success') {
                this.lastModified.notes = data.server_time;
                
                if (data.items && data.items.length > 0) {
                    await this.handleNotesUpdate(data.items);
                }
            }
        } catch (error) {
            console.error('[ConditionalPoller] error polling notes:', error);
        }
    }
    
    async pollAll() {
        if (this.isUserIdle || this.isTabHidden) {
            return;
        }
        
        await this.pollComments();
        
        switch (this.activeTab) {
            case 'media':
                await this.pollMedia();
                break;
            case 'documents':
                await this.pollDocuments();
                break;
            case 'notes':
                await this.pollNotes();
                break;
        }
        
        this.timerId = setTimeout(() => this.pollAll(), this.interval);
    }
    
    startPolling() {
        if (this.timerId) {
            clearTimeout(this.timerId);
        }
        this.pollAll();
    }
    
    stopPolling() {
        if (this.timerId) {
            clearTimeout(this.timerId);
            this.timerId = null;
        }
    }
    
    async handleCommentsUpdate(comments) {
        const callback = this.callbacks.onFetchCommentUpdates;
        
        if (callback.callbackOverride && callback.handler) {
            await callback.handler(comments);
        } else {
            await this.defaultCommentsHandler(comments);
            
            if (callback.handler) {
                await callback.handler(comments);
            }
        }
    }
    
    async handleMediaUpdate(mediaType, items) {
        const callback = this.callbacks.onFetchMediaUpdates;
        
        if (callback.callbackOverride && callback.handler) {
            await callback.handler(mediaType, items);
        } else {
            await this.defaultMediaHandler(mediaType, items);
            
            if (callback.handler) {
                await callback.handler(mediaType, items);
            }
        }
    }
    
    async handleDocumentsUpdate(documents) {
        const callback = this.callbacks.onFetchDocumentUpdates;
        
        if (callback.callbackOverride && callback.handler) {
            await callback.handler(documents);
        } else {
            await this.defaultDocumentsHandler(documents);
            
            if (callback.handler) {
                await callback.handler(documents);
            }
        }
    }
    
    async handleNotesUpdate(notes) {
        const callback = this.callbacks.onFetchNoteUpdates;
        
        if (callback.callbackOverride && callback.handler) {
            await callback.handler(notes);
        } else {
            await this.defaultNotesHandler(notes);
            
            if (callback.handler) {
                await callback.handler(notes);
            }
        }
    }
    
    async defaultCommentsHandler(comments) {
        if (window.docViewerInstance && typeof window.docViewerInstance.updateSharedComments === 'function') {
            await window.docViewerInstance.updateSharedComments(comments);
        }
    }
    
    async defaultMediaHandler(mediaType, items) {
        // mediaType is 'audio', 'video', or 'image'
        if (window.DocViewer && typeof window.DocViewer.refreshMedia === 'function') {
            await window.DocViewer.refreshMedia(mediaType, items);
        }
    }
    
    async defaultDocumentsHandler(documents) {
        if (window.DocViewer && typeof window.DocViewer.refreshDocuments === 'function') {
            await window.DocViewer.refreshDocuments(documents);
            // this.showToast('success', `${documents.length} new document(s) uploaded`);
        } else {
            // this.showToast('info', `${documents.length} new document(s) uploaded`);
        }
    }
    
    async defaultNotesHandler(notes) {
        if (window.DocViewer && typeof window.DocViewer.refreshNotes === 'function') {
            await window.DocViewer.refreshNotes(notes);
            // this.showToast('success', `${notes.length} new note(s) added`);
        } else {
            // this.showToast('info', `${notes.length} new note(s) added`);
        }
    }
    
    showToast(type, message) {
        if (typeof CustomMessage !== 'undefined') {
            CustomMessage[type](message);
        } else {
            console.log(`[${type.toUpperCase()}] ${message}`);
        }
    }
}

export default ConditionalPoller;
